const r=new Set(["completed","succeeded","partial","partially_completed"]),o=new Set(["failed","cancelled","expired","error","rejected"]);function t(e){return String(e||"").trim().toLowerCase()}function a(e){return r.has(t(e))}function i(e){return o.has(t(e))}function n(e){return a(e)||i(e)}const s={generationJob(e){return n(e)?!1:1500},comparison(e){return e?1500:!1},fashionRun(e){return n(e)?!1:1500},templatePreparation(e){return["pending","processing"].includes(t(e))?2500:!1}};export{s as p};
